quickStart.codeSnippet:
server {
    listen 80;
    server_name example.com;
    location / {
        proxy_pass http://localhost:8080;
    }
}

import { Plannotator } from 'plannotator';

const workspace = new Plannotator({ agent: 'claude-code' });
workspace.start();

import { loadWebGuidance } from 'modern-web-guidance';

// 코딩 에이전트에 최신 웹 스킬 주입
loadWebGuidance({ targetAgent: 'copilot' });

import { CodeReviewEngine } from '@alibaba-group/open-code-review';

const engine = new CodeReviewEngine({
  provider: 'openai',
  apiKey: process.env.OPENAI_API_KEY,
  ruleset: ['security', 'thread-safety']
});

await engine.reviewPullRequest({ repo: 'my-org/my-repo', prNumber: 42 });

import { createDevToolsServer } from 'chrome-devtools-mcp';

const server = createDevToolsServer({
  port: 9222,
  headless: false
});

await server.start();

import { AgUiClient } from '@ag-ui/core';

const client = new AgUiClient({ endpoint: 'https://api.your-agent.com' });
client.on('agentStateUpdate', (state) => {
  console.log('Current Agent State:', state);
});

import { Button, ThemeProvider } from '@astryxdesign/core';

export default function App() {
  return (
    <ThemeProvider theme="default">
      <Button variant="primary">AI Ready Button</Button>
    </ThemeProvider>
  );
}

